/**
 * The Google Fonts families offered in the Fonts panel — the 400 most
 * popular Latin families, generated by `scripts/build-font-catalog.mjs`.
 *
 * DO NOT EDIT BY HAND. Rerun that script to refresh the list.
 *
 * It is baked in rather than fetched because Google's catalogue endpoint sends
 * no CORS headers; the stylesheet and font files the app actually downloads are
 * fetched live and need no list of their own.
 */

export interface GoogleFontEntry {
  family: string;
  category: string;
  /** Every weight `css2` will serve for this family, ascending. */
  weights: number[];
  /** Whether the family has a real italic, as opposed to none at all. */
  italic: boolean;
}

